sect1.example:
  &finally; block सहित Throwable error handling


<?php
function inverse($x) {
    return 1/$x;
}

try {
    echo inverse(5) . "\n";
} catch (DivisionByZeroError $e) {
    echo 'Caught error: ', $e->getMessage(), "\n";
} finally {
    echo "First finally.\n";
}

try {
    echo inverse(0) . "\n";
} catch (DivisionByZeroError $e) {
    echo 'Caught error: ', $e->getMessage(), "\n";
} finally {
    echo "Second finally.\n";
}

// Execution जारी राख्नुहोस्
echo "Hello World\n";


  &example.outputs.8;


0.2
First finally.
Caught error: Division by zero
Second finally.
Hello World

  सबै &finally; blocks execute हुनेछन्


<?php
try {
    try {
        throw new Exception();
    } finally {
        echo "Inner finally\n";
    }
} catch (Exception $e) {
} finally {
    echo "Outer finally\n";
}


  &example.outputs;


Inner finally
Outer finally

sect2.example:
   &finally; block भित्रको &return; र अघिल्लो &return; बीचको अन्तरक्रिया


<?php
function testReturnTry() {
    try {
        echo 'Within try', "\n";
        return 'try';
    } finally {
        echo 'Within finally', "\n";
        return 'finally';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        echo 'Within catch', "\n";
        return 'catch';
    } finally {
        echo 'Within finally', "\n";
        return 'finally';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";



   &example.outputs;


Within try
Within finally
finally
Within catch
Within finally
finally

   &finally; block र &return; बीचको अन्तरक्रिया


<?php
function testReturnTry() {
    try {
        return 'try';
    } finally {
        echo 'finally ';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        return 'catch';
    } finally {
        echo 'finally ';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";


   &example.outputs;


finally try
finally catch

   &finally; मा &return; गर्दा फेरि throw गरिएको exception हट्छ


<?php
function process() {
    try {
        throw new Exception('Original exception');
    } catch (Exception $e) {
        echo 'Caught: ', $e->getMessage(), "\n";
        throw $e;
    } finally {
        echo 'Within finally', "\n";
        return 'finally';
    }
}

try {
    echo process(), "\n";
} catch (Exception $e) {
    echo 'This is never reached', "\n";
}


   &example.outputs;


Caught: Original exception
Within finally
finally

   try र finally मा exception


<?php

try {
    try {
        throw new Exception(message: 'Third', previous: new Exception('Fourth'));
    } finally {
        throw new Exception(message: 'First', previous: new Exception('Second'));
    }
} catch (Exception $e) {
    var_dump(
        $e->getMessage(),
        $e->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getPrevious()->getMessage(),
    );
}


   &example.outputs;


string(5) "First"
string(6) "Second"
string(5) "Third"
string(6) "Fourth"


    Exception throw भएको बेला &finally; block
    execute हुनु



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch (Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch (Exception $e) {
    echo 'outer catch';
}


   &example.outputs.similar;


1
finally
outer catch


    Exception throw भएको बेला &finally; block मा
    &yield; गर्दा आउने error



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch (Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
        yield 3;
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch (Exception $e) {
    echo 'outer catch';
}


   &example.outputs.similar;


